serving_render = _build_serving_render(mock_engine)

request = ChatCompletionRequest(
        model=MODEL_NAME,
        messages=[{"role": "user", "content": "Test prompt"}],
    )

result = await serving_render.render_chat_request(request)

assert result.token_ids == [1, 2, 3]
