@pytest.mark.parametrize("format_value", [None, {}])
def test_structural_tag_response_format_invalid(format_value):
    """Malformed structural tags should be rejected during request validation."""
    with pytest.raises(
        ValidationError,
        match="Invalid response_format structural_tag",
    ):
        ChatCompletionRequest(
            model=MODEL_NAME,
            messages=[{"role": "user", "content": "hello"}],
            response_format={"type": "structural_tag", "format": format_value},
        )

@pytest.mark.parametrize("format_value", [None, {}])
def test_batch_structural_tag_response_format_invalid(format_value):
    """Batch chat should reject malformed structural tags at request parsing."""
    with pytest.raises(
        ValidationError,
        match="Invalid response_format structural_tag",
    ):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            response_format={"type": "structural_tag", "format": format_value},
        )

@pytest.mark.parametrize(
    ("unsupported_field", "value", "error"),
    [
        ("stream", True, "do not support streaming"),
        (
            "tools",
            [
                {
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ],
            "do not support tools",
        ),
    ],
)
def test_batch_chat_rejects_unsupported_fields(unsupported_field, value, error):
    with pytest.raises(ValidationError, match=error):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            **{unsupported_field: value},
        )","content_hash":"b371535983d0797524bb0f32ec81a10e04c920c60db5fcae32cd8de0f0f81e6f","chunk_metadata":{"ordinal":9,"document_path":"/code/vllm/tests/entrypoints/openai/chat_completion/test_chat_error.py","document_kind":"source","workspace":"task/marcus-reed-vllm-50026","team":""}}},"conflict_id":null,"change_id":"qdrant:48d45f0a4d41e228f7642d1b"},{"table":"knowledge","key":{"id":"enterprise_c66598ecca20be3daf5fb82d:00010"},"change":"modified","before":{"id":"enterprise_c66598ecca20be3daf5fb82d:00010","vector":{"bm25":{"indices":[19522071,70186382,74221978,199587935,243669559,250826051,264741300,362932159,420652329,448220673,454222729,672845687,757424159,766710245,772165269,829662351,926244272,996611386,1002394412,1190187365,1263925004,1331432587,1430125705,1519078073,1659308796,1684396426,1721384439,1742836257,1810453357,1828930509,1853176582,1889329599,2021929150],"values":[1.4978724,1.4978724,1.7822785,1.4978724,1.4978724,1.9692308,1.4978724,1.4978724,1.9692308,1.4978724,1.4978724,1.7822785,1.7822785,1.4978724,1.4978724,1.4978724,1.4978724,1.4978724,1.4978724,1.7822785,1.4978724,1.7822785,1.4978724,1.4978724,1.4978724,1.7822785,1.7822785,1.7822785,1.4978724,1.4978724,1.4978724,1.4978724,1.7822785]}},"payload":{"chunk_id":"enterprise_c66598ecca20be3daf5fb82d:00010","document_id":"enterprise_c66598ecca20be3daf5fb82d","content_hash":"a69ec810a8ad33b6de2fd5663d1fae309b6d94f52bd4feb0ae8f1b7c6ae75f5c","chunk_metadata":{"workspace":"vllm","ordinal":10,"repository":"vllm","document_kind":"source","connector":"codebase","document_path":"/code/vllm/tests/entrypoints/openai/chat_completion/test_chat_error.py","language":"py"},"ordinal":10,"text":"[Document context]
