              "text": "[Document context]\nTitle: vLLM batch chat request protocol\nSource: vllm pinned source\nPath: /code/vllm/vllm/entrypoints/openai/chat_completion/protocol.py\nWorkspace: task/marcus-reed-vllm-50026\n\nclass ChatCompletionRequest(OpenAIBaseModel):\n    # Ordered by official OpenAI API documentation\n    # https://platform.openai.com/docs/api-reference/chat/create\n    messages: list[ChatCompletionMessageParam]\n    model: str | None = None\n    frequency_penalty: float | None = 0.0\n    logit_bias: dict[str, float] | None = None\n    logprobs: bool | None = False\n    top_logprobs: int | None = 0\n    max_tokens: int | None = Field(\n        default=None,\n        deprecated=\"max_tokens is deprecated in favor of \"\n        \"the max_completion_tokens field\",\n    )\n    max_completion_tokens: int | None = None\n    n: int | None = 1\n    presence_penalty: float | None = 0.0\n    response_format: AnyResponseFormat | None = None\n    seed: int | None = Field(None, ge=_INT64_MIN, le=_INT64_MAX)\n    stop: str | list[str] | None = []\n    stream: bool | None = False\n    stream_options: StreamOptions | None = None\n    temperature: float | None = None\n    top_p: float | None = None\n    tools: list[ChatCompletionToolsParam] | None = None\n    tool_choice: (\n        Literal[\"none\"]\n        | Literal[\"auto\"]\n        | Literal[\"required\"]\n        | ChatCompletionNamedToolChoiceParam\n        | None\n    ) = \"none\"\n    reasoning_effort: (\n        Literal[\"none\", \"minimal\", \"low\", \"medium\", \"high\", \"xhigh\", \"max\"] | None\n    ) = Field(\n        default=None,\n        description=(\n            \"Constrains effort on reasoning for reasoning models. \"\n            \"Currently supported values are none, minimal, low, medium, \"\n            \"high, xhigh, and max. Reducing reasoning effort can result in \"\n            \"faster responses and fewer tokens used on reasoning in a response. \"\n            \"Note that 'max' is