              "text": "[Document context]\nTitle: vLLM batch chat request protocol\nSource: vllm pinned source\nPath: /code/vllm/vllm/entrypoints/openai/chat_completion/protocol.py\nWorkspace: task/marcus-reed-vllm-50026\n\nWe recommend that each document should be a dict containing \"\n            '\"title\" and \"text\" keys.'\n        ),\n    )\n    chat_template: str | None = Field(\n        default=None,\n        description=(\n            \"A Jinja template to use for this conversion. \"\n            \"As of transformers v4.44, default chat template is no longer \"\n            \"allowed, so you must provide a chat template if the tokenizer \"\n            \"does not define one.\"\n        ),\n    )\n    chat_template_kwargs: dict[str, Any] | None = Field(\n        default=None,\n        description=(\n            \"Additional keyword args to pass to the template renderer. \"\n            \"Will be accessible by the chat template.\"\n        ),\n    )\n    media_io_kwargs: dict[str, dict[str, Any]] | None = Field(\n        default=None,\n        description=(\n            \"Additional kwargs to pass to the media IO connectors, \"\n            \"keyed by modality. Merged with engine-level media_io_kwargs.\"\n        ),\n    )\n    mm_processor_kwargs: dict[str, Any] | None = Field(\n        default=None,\n        description=(\"Additional kwargs to pass to the HF processor.\"),\n    )\n    structured_outputs: StructuredOutputsParams | None = Field(\n        default=None,\n        description=\"Additional kwargs for structured outputs\",\n    )\n    priority: int = Field(\n        default=0,\n        ge=_INT64_MIN,\n        le=_INT64_MAX,\n        description=(\n            \"The priority of the request (lower means earlier handling; \"\n            \"default: 0). Any priority other than 0 will raise an error \"\n            \"if the served model does not use priority scheduling.\"\n        ),\n    )\n    request_id: str = Field(\n        default_factory=random_uuid,\n        description=(\n            \"The request_id related to this request. If the caller does \"\n            \"not set it, a random_uuid will be generated. This id is used \"\n            \"through out the inference process and return in response.\"\n        ),\n    )",
